Resta da verificare che il vettore $\pi$ di componenti $\pi_v = d(v)/2m$ soddisfi
$\pi = \pi P$, cioè che per ogni $u \in V$ valga $\pi_u = \sum_{v} \pi_v \, P_{v,u}$.
Poiché $P_{v,u} \neq 0$ soltanto se $(v,u) \in E$, e in tal caso $P_{v,u} = 1/d(v)$,
\[
  \frac{d(u)}{2m}
  \;\stackrel{?}{=}\;
  \sum_{(v,u) \in E} \frac{d(v)}{2m} \cdot P_{v,u}
  \;=\;
  \sum_{(v,u) \in E} \frac{d(v)}{2m} \cdot \frac{1}{d(v)}
  \;=\;
  \frac{1}{2m} \sum_{(v,u) \in E} 1
  \;=\;
  \frac{d(u)}{2m} \,,
\]
perché gli archi incidenti a $u$ sono esattamente $d(u)$. \hfill$\square$

Ergo, per ogni $v \in V$, il tempo medio di ritorno in $v$ --- che in una catena
irriducibile e aperiodica è il reciproco della probabilità stazionaria --- vale
\[
  h_{v,v} \;=\; \frac{1}{\pi_v} \;=\; \frac{2m}{d(v)} \,.
\]

\begin{definizione}[Hitting time, commute time, cover time]
Sia $G = (V,E)$ un grafo connesso e non orientato, e si consideri il random walk su $G$.
\begin{itemize}
  \item $h_{u,v}$ --- \emph{hitting time}: numero medio di passi per andare da $u$ a $v$.
  \item $C_{u,v}$ --- \emph{commute time}:
    \[
      h_{u,v} + h_{v,u} \;=\; C_{u,v} \;=\; C_{v,u} \,.
    \]
  \item $C_u(G)$ --- tempo medio per tornare a $u$ dopo aver visitato l'intero $G$
    partendo da $u$.
  \item $C(G)$ --- \emph{cover time} di $G$:
    \[
      C(G) \;=\; \max_{u} \, C_u(G) \,.
    \]
\end{itemize}
\end{definizione}

